changeSet.sql:
INSERT INTO role (role, description, uuid) SELECT 'Admision', legacy.description, UUID() FROM role legacy WHERE legacy.role = 'SIHSALUS Admision' AND NOT EXISTS ( SELECT 1 FROM role canonical WHERE canonical.role = 'Admision' );
INSERT IGNORE INTO user_role (user_id, role) SELECT user_id, 'Admision' FROM user_role WHERE role = 'SIHSALUS Admision';
INSERT IGNORE INTO role_privilege (role, privilege) SELECT 'Admision', privilege FROM role_privilege WHERE role = 'SIHSALUS Admision';
INSERT IGNORE INTO role_role (parent_role, child_role) SELECT DISTINCT CASE WHEN parent_role = 'SIHSALUS Admision' THEN 'Admision' ELSE parent_role END, CASE WHEN child_role = 'SIHSALUS Admision' THEN 'Admision' ELSE child_role END FROM role_role WHERE ( parent_role = 'SIHSALUS Admision' OR child_role = 'SIHSALUS Admision' ) AND CASE WHEN parent_role = 'SIHSALUS Admision' THEN 'Admision' ELSE parent_role END <> CASE WHEN child_role = 'SIHSALUS Admision' THEN 'Admision' ELSE child_role END;
DELETE FROM user_role WHERE role = 'SIHSALUS Admision'; DELETE FROM role_privilege WHERE role = 'SIHSALUS Admision'; DELETE FROM role_role WHERE parent_role = 'SIHSALUS Admision' OR child_role = 'SIHSALUS Admision';

